import{_ as a,o as i,c as e,a6 as t}from"./chunks/framework.De615z8S.js";const c=JSON.parse('{"title":"批量任务与返工记录","description":"","frontmatter":{"id":"batch","title":"批量任务与返工记录","chapter":"12","status":"已公开","evidence_status":"按原稿重写并核对官方操作资料；未执行生图、软件操作或平台上传","last_modified":"2026-10-14T00:00:00.000Z","resource_ids":["footwear-skills","ecommerce-skills"],"order":42,"content_kind":"方法说明"},"headers":[],"relativePath":"workflows/batch.md","filePath":"workflows/batch.md"}'),n={name:"workflows/batch.md"};function h(l,s,p,r,o,d){return i(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="批量任务与返工-先让状态对应实际文件" tabindex="-1">批量任务与返工，先让状态对应实际文件 <a class="header-anchor" href="#批量任务与返工-先让状态对应实际文件" aria-label="Permalink to &quot;批量任务与返工，先让状态对应实际文件&quot;">​</a></h1><p>批量前先做完一个真实任务，再扩大清单。本节做出任务表与返工记录，适用于商品图、品牌KV、内容卡和语言版本。生成服务的任务回执、已经下载的图片、已核对的成品、已上传平台的内容分别记录。</p><h2 id="_1-一行一项任务" tabindex="-1">1. 一行一项任务 <a class="header-anchor" href="#_1-一行一项任务" aria-label="Permalink to &quot;1. 一行一项任务&quot;">​</a></h2><p>用task_id关联素材和结果，每行列输入文件、提示词版本、用途、输出文件、实际状态与问题。图片制作不一定调用生成，有的直接在图层软件处理。失败时保持原任务ID，别因为生成慢就重复提交。</p><div class="language-csv vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">task_id,</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">input,</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">position,</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">output,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">status,</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">issue</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">JB01-01-main,</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">JB01_white_front.jpg,</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">main,</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">JB01_white_01-main_zh_v01.jpg,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">planned,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">JB01-02-scene,</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">JB01_white_front.jpg,</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scene,</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">JB01_white_02-scene_zh_v01.jpg,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">planned,</span></span></code></pre></div><h2 id="_2-记录一次具体返工" tabindex="-1">2. 记录一次具体返工 <a class="header-anchor" href="#_2-记录一次具体返工" aria-label="Permalink to &quot;2. 记录一次具体返工&quot;">​</a></h2><p>假设场景图左上水果遮住标题，返工写“02-scene，背景层左上区域，移水果，保持商品和光向”。然后做v02，查看标题区域和真实商品有没有一起变。若整图模型改了产品，回真实商品层合成。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>根据任务表和当前文件清单整理返工。只处理有具体问题的行，每行给问题、要修改的区域或图层、保持内容、修改后的文件名和复核项目。</span></span>
<span class="line"><span>没有实际文件的任务不标完成。下载失败优先重试原结果下载，不重新生成。产品结构错误回真实素材，参数错误改文字层，裁切错误改输出尺寸。保留原任务ID与旧版本，避免重复执行成功任务。</span></span></code></pre></div><h2 id="_3-检查输出而非只看任务数" tabindex="-1">3. 检查输出而非只看任务数 <a class="header-anchor" href="#_3-检查输出而非只看任务数" aria-label="Permalink to &quot;3. 检查输出而非只看任务数&quot;">​</a></h2><p>逐行核文件存在、能打开、宽高、颜色/变体、文字和图片位置。输出文件名不同不代表图像内容不同，五张重复背景也不算五种用途。交付选用版本和清单，源文件缺失明确写未交付。</p><p>跨境例子与目录操作见<a href="./../ecommerce/cross-border-sku-delivery">SKU交付教程</a>，真实商品逐图制作见<a href="./../ecommerce/image-set">套图教程</a>。本节是文件与状态方法，没有提交真实图像任务。</p>`,11)])])}const _=a(n,[["render",h]]);export{c as __pageData,_ as default};
